refused_program.body:
set -e
git fetch {upstream_remote}
merge_rc=0
git merge --no-edit {upstream_remote}/{upstream_branch} || merge_rc=$?
if [ "$merge_rc" -ne 0 ] && ! git rev-parse -q --verify MERGE_HEAD >/dev/null; then
  exit 1
fi
if git rev-parse -q --verify MERGE_HEAD >/dev/null; then
  tmp=$(mktemp -d)
  trap 'rm -rf "$tmp"' EXIT
  while IFS= read -r -d '' f; do
    base="$tmp/base"
    ours="$tmp/ours"
    theirs="$tmp/theirs"
    diff="$tmp/diff"
    have_base=1
    if git cat-file -e ":1:$f" 2>/dev/null; then
      git show ":1:$f" > "$base"
    else
      : > "$base"
      have_base=0
    fi
    if ! git cat-file -e ":2:$f" 2>/dev/null; then
      git rm -f --quiet -- "$f" 2>/dev/null || true
      continue
    fi
    git show ":2:$f" > "$ours"
    if ! git cat-file -e ":3:$f" 2>/dev/null; then
      cat "$ours" > "$f"
      git add -- "$f"
      continue
    fi
    git show ":3:$f" > "$theirs"
    if [ "$have_base" -eq 0 ]; then
      cat "$ours" > "$f"
      git add -- "$f"
      continue
    fi
    git diff --no-index -U0 -- "$base" "$theirs" > "$diff" || true
    awk -v ours="$ours" -v theirs="$theirs" -v base="$base" '
      function emit(b,   k, line) {
        for (k = 1; k <= blen[b]; k++) {
          line = bline[b, k]
          if (!(line in firstO) && !(line in inBase) && !(line in emitted)) {
            print line
            emitted[line] = 1
          }
        }
      }
      function record(   b, k, follow, prev, idx, mode) {
        if (!pure || ai == 0) return
        b = ++nb
        for (k = 1; k <= ai; k++) bline[b, k] = A[k]
        blen[b] = ai
        follow = L + ai
        prev = L - 1
        mode = ""
        idx = 0
        if (follow <= tn && (T[follow] in firstO)) {
          mode = "before"; idx = firstO[T[follow]]
        } else if (prev >= 1 && (T[prev] in firstO)) {
          mode = "after"; idx = lastO[T[prev]]
        } else {
          for (k = prev; k >= 1; k--) {
            if (T[k] in firstO) { mode = "after"; idx = lastO[T[k]]; break }
          }
          if (mode == "") {
            for (k = follow; k <= tn; k++) {
              if (T[k] in firstO) { mode = "before"; idx = firstO[T[k]]; break }
            }
          }
          if (mode == "") { mode = "append"; idx = 0 }
        }
        bmode[b] = mode
        bidx[b] = idx
      }
      BEGIN {
        while ((getline line < base) > 0) inBase[line] = 1
        close(base)
        on = 0
        while ((getline line < ours) > 0) {
          O[++on] = line
          if (!(line in firstO)) firstO[line] = on
          lastO[line] = on
        }
        close(ours)
        tn = 0
        while ((getline line < theirs) > 0) {
          T[++tn] = line
        }
        close(theirs)
        nb = 0
        pure = 0
        ai = 0
      }
      /^@@ / {
        if (pure) record()
        old = substr($2, 2)
        new = substr($3, 2)
        split(old, oa, ",")
        split(new, na, ",")
        oldcount = (2 in oa) ? oa[2] + 0 : 1
        L = na[1] + 0
        newcount = (2 in na) ? na[2] + 0 : 1
        pure = (oldcount == 0 && newcount > 0)
        ai = 0
        next
      }
      pure && /^\+/ && !/^\+\+\+/ {
        ++ai
        A[ai] = substr($0, 2)
        next
      }
      END {
        if (pure) record()
        for (i = 1; i <= on; i++) {
          for (b = 1; b <= nb; b++) {
            if (!done[b] && bmode[b] == "before" && bidx[b] == i) {
              emit(b)
              done[b] = 1
            }
          }
          print O[i]
          for (b = 1; b <= nb; b++) {
            if (!done[b] && bmode[b] == "after" && bidx[b] == i) {
              emit(b)
              done[b] = 1
            }
          }
        }
        for (b = 1; b <= nb; b++) {
          if (!done[b]) {
            emit(b)
            done[b] = 1
          }
        }
      }
    ' "$diff" > "$f"
    git add -- "$f"
  done < <(git diff --name-only --diff-filter=U -z)
  git commit --no-edit
fi
